/* My Vocabulary — local-first language learning app */
(() => {
'use strict';
const KEY='myVocabularyData_v1';
const $=s=>document.querySelector(s);
const uid=()=>`${Date.now().toString(36)}${Math.random().toString(36).slice(2,8)}`;
const today=()=>new Date().toISOString().slice(0,10);
const dateAdd=(date,days)=>{const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+days);return d.toISOString().slice(0,10)};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaults=()=>({version:1,languages:[{id:'en',name:'English',nativeName:'영어',createdAt:new Date().toISOString()}],activeLanguageId:'en',data:{},settings:{theme:'cream',defaultStudyMode:'flashcard',defaultQuestionCount:10,autoSpeakCopyNext:false},goals:{daily:10,weekly:50,monthly:200},rewards:[],records:[],wrongNotes:[],sessions:[]});
let state=load(),page='dashboard',wordFilter='',wordSort='recent',selectedIds=new Set(),study=null,quiz=null,reviewQueue=[],reviewIndex=0;
function load(){try{const x=JSON.parse(localStorage.getItem(KEY));return x&&x.version?{...defaults(),...x}:defaults()}catch{return defaults()}}
function save(){localStorage.setItem(KEY,JSON.stringify(state));}
function lang(){return state.activeLanguageId}
function bucket(){if(!state.data[lang()])state.data[lang()]={words:[],wordbooks:[]};return state.data[lang()]}
function words(){return bucket().words}
function books(){return bucket().wordbooks}
function word(id){return words().find(w=>w.id===id)}
function notify(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>t.classList.remove('show'),2300)}
function nav(p){page=p;selectedIds.clear();study=null;quiz=null;render()}
const titles={
dashboard:['학습 현황','대시보드'],
words:['단어 관리','내 단어'],
wordbooks:['단어 정리','단어장'],
study:['영어 학습','단어 학습'],
quiz:['학습 평가','테스트'],
review:['반복 학습','복습'],
wrong:['오답 관리','오답 노트'],
statistics:['학습 분석','학습 통계'],
goals:['학습 동기','목표와 보상'],
friends:['함께 학습하기','친구'],
settings:['환경 설정','설정']
};
function render(){const t=titles[page];$('#pageEyebrow').textContent=t[0];$('#pageTitle').textContent=t[1];document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#activeLanguage').innerHTML=state.languages.map(l=>`<option value="${esc(l.id)}" ${l.id===lang()?'selected':''}>${esc(l.name)}</option>`).join('');$('#todayLabel').textContent=new Date().toLocaleDateString('ko-KR',{year:'numeric',month:'long',day:'numeric',weekday:'short'});const fn={dashboard:dashboardPage,words:wordsPage,wordbooks:booksPage,study:studyPage,quiz:quizPage,review:reviewPage,wrong:wrongPage,statistics:statsPage,goals:goalsPage,settings:settingsPage,friends:friendsPage};$('#pageContent').innerHTML=`<div class="language-tabs">${state.languages.map(l=>`<div class="language-tab-group"><button class="language-tab ${l.id===lang()?'active':''}" data-language-tab="${esc(l.id)}">${esc(l.nativeName||l.name)}</button><button class="language-tool" data-language-edit="${esc(l.id)}">수정</button><button class="language-tool danger" data-language-delete="${esc(l.id)}">삭제</button></div>`).join('')}<button class="language-tab" id="inlineAddLanguage">＋ 언어 추가</button></div>`+fn[page]();bindPage();$('#sidebar').classList.remove('open')}
function stat(label,value,note=''){return `<div class="card stat-card"><div class="stat-label">${label}</div><div class="stat-value">${value}</div><div class="stat-note">${note}</div></div>`}
function progress(label,n,goal){let pct=goal?Math.min(100,Math.round(n/goal*100)):0;return `<div class="goal-row"><div class="goal-meta"><span>${label}</span><strong>${n} / ${goal||'—'} <span class="muted">(${pct}%)</span></strong></div><div class="progress"><span style="width:${pct}%"></span></div></div>`}
function periodCount(period){let now=new Date(),start=new Date(now);if(period==='daily')start.setHours(0,0,0,0);if(period==='weekly'){start.setDate(now.getDate()-((now.getDay()+6)%7));start.setHours(0,0,0,0)}if(period==='monthly'){start.setDate(1);start.setHours(0,0,0,0)}return words().filter(w=>w.status==='mastered'&&(w.reviewStage||0)>=5&&w.masteredAt&&new Date(w.masteredAt)>=start).length}
function dueWords(){return words().filter(w=>w.nextReviewAt&&w.nextReviewAt<=today())}
function todayUnique(){return new Set(state.records.filter(r=>r.languageId===lang()&&r.studiedAt.slice(0,10)===today()).map(r=>r.wordId)).size}
function accuracy(records){let a=records.filter(r=>typeof r.isCorrect==='boolean');return a.length?Math.round(a.filter(r=>r.isCorrect).length/a.length*100):0}
function dashboardPage(){const ws=words(),done=ws.filter(w=>w.status==='mastered'&&(w.reviewStage||0)>=5).length,records=state.records.filter(r=>r.languageId===lang()),tod=records.filter(r=>r.studiedAt.slice(0,10)===today());let streak=0,d=today();const days=new Set(records.map(r=>r.studiedAt.slice(0,10)));while(days.has(d)){streak++;d=dateAdd(d,-1)}const newToday=ws.filter(w=>!w.lastStudiedAt).length;return `
<div class="grid stats-grid">${stat('전체 단어 수',ws.length,'현재 언어에 등록된 단어')}${stat('암기 완료',done,`${ws.length?Math.round(done/ws.length*100):0}% 완료`)}${stat("오늘의 학습 단어",todayUnique(),'오늘 학습한 고유 단어')}${stat("오늘의 정답률",`${accuracy(tod)}%`,`${tod.filter(r=>typeof r.isCorrect==='boolean').length}개 채점 기록`)}</div>
<div class="grid two-col"><div class="card"><div class="section-heading" style="margin:0 0 16px"><div><h2>오늘의 학습</h2><p>오늘의 학습을 이어가세요.</p></div><span class="tag">${dueWords().length}개 복습 예정</span></div><div class="quick-actions"><button class="btn primary" data-go="study">학습 시작</button><button class="btn" data-go="review">복습하기</button><button class="btn" data-go="quiz">테스트 시작</button></div><div class="section-heading"><h2>학습 목표</h2><button class="btn" data-go="goals">목표 설정</button></div>${progress('일간',periodCount('daily'),state.goals.daily)}${progress('주간',periodCount('weekly'),state.goals.weekly)}${progress('월간',periodCount('monthly'),state.goals.monthly)}</div>
<div class="card"><h3>Learning snapshot</h3><div class="activity-item"><span>복습 예정 단어</span><strong>${dueWords().length}</strong></div><div class="activity-item"><span>오답 노트</span><strong>${state.wrongNotes.filter(x=>x.languageId===lang()).length}</strong></div><div class="activity-item"><span>연속 학습 일수</span><strong>${streak} days</strong></div><div class="activity-item"><span>최근 테스트 정답률</span><strong>${accuracy(records.slice(-30))}%</strong></div></div></div>
<div class="section-heading"><div><h2>Recent activity</h2><p>최근 학습 기록</p></div><button class="btn" data-go="statistics">통계 보기</button></div><div class="card">${records.length?records.slice(-6).reverse().map(r=>{let w=word(r.wordId);return `<div class="activity-item"><span><strong>${esc(w?.word||'삭제된 단어')}</strong> · ${esc(r.studyType)}</span><span class="muted">${new Date(r.studiedAt).toLocaleString('ko-KR')}</span></div>`}).join(''):'<div class="empty">아직 학습 기록이 없습니다.</div>'}</div>`}
function wordsPage(){let arr=[...words()];if(wordFilter)arr=arr.filter(w=>(w.word+' '+w.meanings.join(' ')+' '+w.memo).toLowerCase().includes(wordFilter.toLowerCase()));let status=$('#statusFilter')?.value||'all',bookId=$('#bookFilter')?.value||'all';if(status!=='all')arr=arr.filter(w=>w.status===status);if(bookId!=='all')arr=arr.filter(w=>w.wordbookIds.includes(bookId));arr.sort((a,b)=>wordSort==='alpha'?a.word.localeCompare(b.word):new Date(b.createdAt)-new Date(a.createdAt));return `<div class="toolbar"><input class="search" id="wordSearch" placeholder="단어 또는 뜻 검색..." value="${esc(wordFilter)}"><select id="statusFilter"><option value="all">모든 암기 상태</option><option value="learning">학습 중</option><option value="review">복습 중</option><option value="mastered">암기 완료</option></select><select id="bookFilter"><option value="all">모든 단어장</option>${books().map(b=>`<option value="${b.id}">${esc(b.name)}</option>`).join('')}</select><select id="sortWords"><option value="recent" ${wordSort==='recent'?'selected':''}>최근 추가순</option><option value="alpha" ${wordSort==='alpha'?'selected':''}>알파벳순</option></select><button class="btn primary" id="addWord">＋ 단어 추가</button></div>
<div class="toolbar"><label class="small"><input type="checkbox" id="selectAll" class="checkbox"> 전체 선택</label><span class="muted small">${selectedIds.size}개 선택</span><button class="btn danger" id="bulkDelete" ${selectedIds.size?'':'disabled'}>선택 삭제</button><span class="muted small">${arr.length} words</span></div>
<div class="table-wrap">${arr.length?`<table><thead><tr><th></th><th>WORD</th><th>MEANING</th><th>PART OF SPEECH</th><th>STATUS</th><th>REVIEW</th><th></th></tr></thead><tbody>${arr.map(w=>`<tr><td><input type="checkbox" class="checkbox row-select" data-id="${w.id}" ${selectedIds.has(w.id)?'checked':''}></td><td><button class="word-link" data-detail="${w.id}" style="border:0;background:none;padding:0;text-align:left"><span class="word-cell">${esc(w.word)}</span></button></td><td>${esc(w.meanings.join(', '))}</td><td>${esc(w.partOfSpeech||'—')}</td><td><span class="tag ${w.status==='mastered'?'':'beige'}">${statusLabel(w.status)}</span></td><td>${w.nextReviewAt||'—'}</td><td><button class="btn" data-edit="${w.id}">수정</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty"><strong>등록된 단어가 없습니다.</strong>단어 추가 버튼으로 첫 단어를 등록해보세요.</div>'}</div>`}
function statusLabel(s){return ({learning:'학습 중',review:'복습 중',mastered:'암기 완료'})[s]||'학습 중'}
function booksPage(){return `<div class="section-heading" style="margin-top:0"><div><h2>My wordbooks</h2><p>단어를 주제별로 정리하세요. 하나의 단어를 여러 단어장에 넣을 수 있습니다.</p></div><button class="btn primary" id="addBook">＋ 단어장 만들기</button></div><div class="grid three-col">${books().map(b=>`<div class="card"><div style="display:flex;justify-content:space-between"><span class="tag">WORDBOOK</span><button class="icon-btn" data-book-edit="${b.id}">···</button></div><h3 style="font-size:17px;margin:17px 0 5px">${esc(b.name)}</h3><p class="muted small">${esc(b.description||'설명 없음')}</p><div class="section-heading"><span class="small muted">${words().filter(w=>w.wordbookIds.includes(b.id)).length} words</span><button class="btn soft" data-book-study="${b.id}">학습하기</button></div></div>`).join('')||'<div class="card empty">아직 단어장이 없습니다.</div>'}</div>`}
function studyPage(){if(!study)return `<div class="grid two-col"><div class="card"><h3>Choose study mode</h3><div class="form-group"><label>학습 방식</label><select id="studyMode"><option value="flashcard">Flashcard · 영어 → 뜻</option><option value="reverse">Reverse Flashcard · 뜻 → 영어</option><option value="example">Example Study · 예문 중심</option><option value="spelling">Spelling Practice · 뜻 → 영어 스펠링 입력</option><option value="copy">Sentence Copy · 예문 따라 쓰기</option></select></div><div class="form-group" style="margin-top:12px"><label>단어장</label><select id="studyBook"><option value="all">전체 단어</option>${books().map(b=>`<option value="${b.id}">${esc(b.name)}</option>`).join('')}</select></div><div class="form-group" style="margin-top:12px"><label>학습 개수</label><input id="studyCount" type="number" min="1" max="500" value="10"></div><div class="form-group" style="margin-top:12px"><label>순서</label><select id="studyOrder"><option value="sequential">순차 학습</option><option value="random">랜덤 학습</option></select></div><button class="btn primary" style="margin-top:18px" id="startStudy">학습 시작</button></div><div class="card"><h3>Study guide</h3><p class="small muted">카드를 보고 스스로 뜻을 떠올린 뒤 답을 확인하세요. 모르겠다고 선택한 단어는 오답 노트에 자동으로 기록됩니다.</p><div class="activity-item"><span>전체 단어</span><strong>${words().length}</strong></div><div class="activity-item"><span>학습 중</span><strong>${words().filter(w=>w.status!=='mastered').length}</strong></div><div class="activity-item"><span>오답 단어</span><strong>${state.wrongNotes.filter(x=>x.languageId===lang()).length}</strong></div></div></div>`;
let w=word(study.ids[study.index]);if(!w)return `<div class="empty">학습할 단어가 없습니다.</div>`;let total=study.ids.length,shown=study.revealed,checked=study.checked;let content=study.mode==='copy'?(()=>{const ex=w.examples?.[0];return `<div class="study-example">${esc(ex?.text||'예문이 등록되지 않았습니다.')}</div><p class="study-meaning">${esc(ex?.translation||'해석이 등록되지 않았습니다.')}</p><div class="form-group" style="max-width:620px;margin:20px auto"><label for="studyCopyAnswer">위 예문을 그대로 입력하세요</label><textarea id="studyCopyAnswer" rows="3" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="Type the sentence" ${checked?'disabled':''}>${esc(study.answer||'')}</textarea><button class="btn primary" id="checkStudyCopy" style="margin-top:10px" ${checked?'disabled':''}>입력 확인</button></div>${checked?`<p class="${study.correct?'stat-note':'muted'}">${study.correct?'정확해요! 문장을 바르게 입력했습니다.':'다시 확인해 보세요. 원문은 다음과 같습니다.'}</p>${!study.correct?`<p class="study-meaning">${esc(ex?.text||'')}</p>`:''}<div class="study-controls"><button class="btn" id="retryStudyCopy">다시 입력하기</button><button class="btn primary" id="studyNextCopy">다음 예문 →</button></div>`:''}`})():study.mode==='spelling'?`<div class="study-word">${esc(w.meanings.join(', '))}</div><div class="form-group" style="max-width:420px;margin:20px auto"><label for="studySpellingAnswer">영어 스펠링을 입력하세요</label><input id="studySpellingAnswer" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="Type the spelling" value="${esc(study.answer||'')}" ${checked?'disabled':''}><button class="btn primary" id="checkStudySpelling" style="margin-top:10px" ${checked?'disabled':''}>정답 확인</button></div>${checked?`<p class="${study.correct?'stat-note':'muted'}">${study.correct?'정답입니다.':'아쉬워요. 정답은 '+esc(w.word)+'입니다.'}</p>`:''}`:study.mode==='example'?`${(w.examples||[]).filter(e=>e.text?.trim()).slice(0,3).map((ex,i)=>`<div class="activity-item" style="display:block;text-align:left;margin:14px 0"><div class="study-example">${highlightWord(ex.text,w.word)}</div><p class="study-meaning">${esc(ex.translation||'해석이 등록되지 않았습니다.')}</p><button class="btn" type="button" data-speak-example="${i}">🔊 이 문장 듣기</button></div>`).join('')||'<p class="muted">등록된 예문이 없습니다.</p>'}<p class="muted small">뜻: ${esc(w.meanings.join(', '))}</p>`:study.mode==='reverse'?`<div class="study-word">${esc(w.meanings[0])}</div><button class="btn" id="revealMeaning">영어 단어 확인</button>${shown?`<div class="study-meaning">${esc(w.word)}</div>`:''}`:`<div class="study-word">${esc(w.word)}</div><button class="btn" id="revealMeaning">뜻 확인</button>${shown?`<div class="study-meaning">${esc(w.meanings.join(', '))}</div>`:''}`;
return `<div class="study-progress">${progress(`WORD ${study.index+1} OF ${total}`,study.index+1,total)}</div><div class="card study-card"><div class="study-kicker">${study.mode.toUpperCase()} · ${esc(w.partOfSpeech||'VOCABULARY')}</div>${content}<button class="btn" id="playStudyPronunciation" type="button" style="margin-top:14px">🔊 ${study.mode==='copy'?'문장 발음 듣기':'발음 듣기'}</button><div class="study-controls">${study.mode==='spelling'||study.mode==='copy'?'':shown?`<button class="btn danger" id="dontKnow">모르겠음</button><button class="btn primary" id="know">알고 있음</button>`:''}</div><div class="study-controls"><button class="btn" id="studyPrev" ${study.index===0?'disabled':''}>← 이전</button><button class="btn" id="studyNext">건너뛰기 →</button><button class="btn" id="endStudy">학습 종료</button></div></div>`}
function highlightWord(text,word){let safe=esc(text);let re=new RegExp(`(${word.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')})`,'ig');return safe.replace(re,'<strong style="color:var(--sage-dark);background:#edf1e8">$1</strong>')}
function quizPage(){if(!quiz)return `<div class="grid two-col"><div class="card"><h3>Quiz setup</h3><div class="form-group"><label>테스트 유형</label><select id="quizMode"><option value="multiple">Multiple Choice</option><option value="typing">Typing Test</option><option value="random">Random Quiz</option></select></div><div class="form-group" style="margin-top:12px"><label>문제 수</label><input id="quizCount" type="number" min="1" max="500" value="10"></div><div class="form-group" style="margin-top:12px"><label>단어장</label><select id="quizBook"><option value="all">전체 단어</option>${books().map(b=>`<option value="${b.id}">${esc(b.name)}</option>`).join('')}</select></div><div class="form-group" style="margin-top:12px"><label>출제 범위</label><select id="quizFilter"><option value="all">전체 단어</option><option value="learning">학습 중</option><option value="review">복습 중</option><option value="mastered">암기 완료</option><option value="wrong">오답 단어만</option></select></div><button class="btn primary" id="startQuiz" style="margin-top:18px">테스트 시작</button></div><div class="card"><h3>Ready to test?</h3><p class="small muted">객관식 보기에는 등록된 다른 단어의 뜻을 사용합니다. 오답은 자동으로 오답 노트에 쌓입니다. 입력형에서는 영어 철자와 한국어 뜻을 모두 연습할 수 있습니다.</p></div></div>`;
if(quiz.done)return `<div class="card study-card"><div class="study-kicker">QUIZ COMPLETE</div><div class="result-number">${Math.round(quiz.correct/quiz.items.length*100)}%</div><h2>테스트 결과</h2><p class="muted small">${quiz.correct} correct · ${quiz.items.length-quiz.correct} incorrect · ${quiz.items.length} questions</p><div class="section-heading"><h2>틀린 단어</h2></div>${quiz.missed.length?quiz.missed.map(w=>`<div class="activity-item"><strong>${esc(w.word)}</strong><span>${esc(w.meanings.join(', '))}</span></div>`).join(''):'<p class="small muted">모든 문제를 맞혔습니다.</p>'}<div class="study-controls"><button class="btn primary" id="retryQuiz">재시험</button><button class="btn" id="endQuiz">완료</button></div></div>`;
let item=quiz.items[quiz.index],w=word(item.id);if(!w)return '<div class="empty">문제를 불러올 수 없습니다.</div>';let prompt=item.direction==='en-ko'?w.word:w.meanings[0];return `<div class="study-progress">${progress(`QUESTION ${quiz.index+1} OF ${quiz.items.length}`,quiz.index+1,quiz.items.length)}</div><div class="card study-card"><div class="study-kicker">${quiz.mode.toUpperCase()} QUIZ · ${item.direction==='en-ko'?'ENGLISH → KOREAN':'KOREAN → ENGLISH'}</div><div class="study-word">${esc(prompt)}</div>${item.type==='multiple'?`<div class="choice-grid">${item.options.map((o,i)=>`<button class="choice ${quiz.answered?(o.correct?'correct':o.value===quiz.selected?'incorrect':''):''}" data-choice="${i}" ${quiz.answered?'disabled':''}>${esc(o.value)}</button>`).join('')}</div>`:`<div class="form-group" style="max-width:420px;margin:20px auto"><input id="quizAnswer" placeholder="${item.direction==='en-ko'?'한국어 뜻 입력':'영어 철자 입력'}" ${quiz.answered?'disabled':''} value="${esc(quiz.answer||'')}"><button class="btn primary" id="checkAnswer" style="margin-top:9px" ${quiz.answered?'disabled':''}>정답 확인</button></div>`}${quiz.answered?`<p class="${quiz.lastCorrect?'stat-note':'muted'}">${quiz.lastCorrect?'정답입니다.':'정답: '+esc(item.direction==='en-ko'?w.meanings.join(', '):w.word)}</p><button class="btn primary" id="nextQuestion">${quiz.index===quiz.items.length-1?'결과 보기':'다음 문제'}</button>`:''}<div class="study-controls"><button class="btn" id="quitQuiz">테스트 종료</button></div></div>`}
function reviewPage(){const due=dueWords();return `<div class="grid two-col"><div class="card"><h3>Due for review</h3><div class="stat-value">${due.length}</div><p class="small muted">오늘 또는 이전 날짜에 복습 예정인 단어</p><button class="btn primary" id="startReview" ${due.length?'':'disabled'}>복습 시작</button></div><div class="card"><h3>Spaced repetition schedule</h3><p class="small muted">성공 시 1 → 3 → 7 → 14 → 30일 간격으로 복습 주기가 늘어납니다. Again은 단계를 초기화하고 다음 날 다시 표시합니다.</p><div class="activity-item"><span>복습 예정</span><strong>${due.length}</strong></div><div class="activity-item"><span>복습 완료 누적</span><strong>${words().reduce((n,w)=>n+(w.reviewHistory?.length||0),0)}</strong></div></div></div><div class="section-heading"><h2>Review schedule</h2></div><div class="table-wrap">${words().filter(w=>w.nextReviewAt).length?`<table><thead><tr><th>WORD</th><th>MEANING</th><th>NEXT REVIEW</th><th>STAGE</th><th>LAST RESULT</th></tr></thead><tbody>${words().filter(w=>w.nextReviewAt).sort((a,b)=>a.nextReviewAt.localeCompare(b.nextReviewAt)).map(w=>`<tr><td class="word-cell">${esc(w.word)}</td><td>${esc(w.meanings.join(', '))}</td><td>${w.nextReviewAt}</td><td>${w.reviewStage||0}/5</td><td>${esc(w.lastReviewResult||'—')}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">아직 복습 일정이 없습니다. 단어를 학습하면 일정이 생성됩니다.</div>'}</div>${reviewQueue.length?reviewCard():''}`}
function reviewCard(){let w=word(reviewQueue[reviewIndex]);if(!w)return '';return `<div class="card study-card"><div class="study-kicker">REVIEW ${reviewIndex+1} / ${reviewQueue.length}</div><div class="study-word">${esc(w.word)}</div><button class="btn" id="reviewReveal">뜻 확인</button><div id="reviewAnswer" class="study-meaning hidden">${esc(w.meanings.join(', '))}</div><div class="study-controls"><button class="btn danger" data-rate="Again">Again</button><button class="btn" data-rate="Hard">Hard</button><button class="btn soft" data-rate="Good">Good</button><button class="btn primary" data-rate="Easy">Easy</button></div></div>`}
function wrongPage(){let list=state.wrongNotes.filter(x=>x.languageId===lang()).sort((a,b)=>b.lastWrongAt.localeCompare(a.lastWrongAt));return `<div class="toolbar"><span class="tag red">${list.length} entries</span><button class="btn primary" id="wrongStudy" ${list.length?'':'disabled'}>오답 단어 학습</button><button class="btn" id="wrongQuiz" ${list.length?'':'disabled'}>오답 단어 테스트</button></div><div class="table-wrap">${list.length?`<table><thead><tr><th>WORD</th><th>MEANING</th><th>WRONG COUNT</th><th>LAST WRONG</th><th>STATUS</th><th></th></tr></thead><tbody>${list.map(x=>{let w=word(x.wordId);return `<tr><td class="word-cell">${esc(w?.word||x.wordSnapshot)}</td><td>${esc(w?.meanings.join(', ')||x.meaningSnapshot)}</td><td>${x.count}</td><td>${new Date(x.lastWrongAt).toLocaleDateString('ko-KR')}</td><td>${statusLabel(w?.status||'learning')}</td><td><button class="btn" data-wrong-delete="${x.wordId}">기록 삭제</button></td></tr>`}).join('')}</tbody></table>`:'<div class="empty"><strong>오답 기록이 없습니다.</strong>학습 또는 테스트에서 모르는 단어를 표시하면 이곳에 기록됩니다.</div>'}</div>`}
function statsPage(){let rec=state.records.filter(r=>r.languageId===lang()),quizRec=rec.filter(r=>r.studyType.includes('quiz'));let daily={};for(let i=6;i>=0;i--){let d=dateAdd(today(),-i);daily[d]=new Set(rec.filter(r=>r.studiedAt.slice(0,10)===d).map(r=>r.wordId)).size}let max=Math.max(1,...Object.values(daily));let frequent=[...words()].sort((a,b)=>b.wrongCount-a.wrongCount).slice(0,5);return `<div class="grid stats-grid">${stat('TOTAL WORDS',words().length,'등록 단어')}${stat('MASTERED',words().filter(w=>w.status==='mastered').length,'암기 완료')}${stat('TODAY STUDIED',daily[today()],'오늘 공부한 단어 수')}${stat('OVERALL ACCURACY',`${accuracy(rec)}%`,'채점 가능한 기록 기준')}</div><div class="grid two-col"><div class="card"><h3>Daily study · last 7 days</h3><div class="bar-chart">${Object.entries(daily).map(([d,n])=>`<div class="bar-col"><span class="small">${n||''}</span><div class="bar" style="height:${n/max*100}%"></div><span class="bar-label">${d.slice(5)}</span></div>`).join('')}</div></div><div class="card"><h3>Study overview</h3><div class="activity-item"><span>누적 테스트 문항</span><strong>${quizRec.length}</strong></div><div class="activity-item"><span>테스트 정답률</span><strong>${accuracy(quizRec)}%</strong></div><div class="activity-item"><span>복습 필요 단어</span><strong>${dueWords().length}</strong></div><div class="activity-item"><span>학습 일수</span><strong>${new Set(rec.map(r=>r.studiedAt.slice(0,10))).size}</strong></div></div></div><div class="grid two-col" style="margin-top:16px"><div class="card"><h3>Most missed words</h3>${frequent.length?frequent.map(w=>`<div class="activity-item"><strong>${esc(w.word)}</strong><span>${w.wrongCount} wrong</span></div>`).join(''):'<div class="empty">기록이 없습니다.</div>'}</div><div class="card"><h3>Wordbook mastery</h3>${books().length?books().map(b=>{let ws=words().filter(w=>w.wordbookIds.includes(b.id)),n=ws.filter(w=>w.status==='mastered').length;return `<div class="goal-row"><div class="goal-meta"><span>${esc(b.name)}</span><strong>${n}/${ws.length}</strong></div><div class="progress"><span style="width:${ws.length?n/ws.length*100:0}%"></span></div></div>`}).join(''):'<div class="empty">단어장을 먼저 만들어보세요.</div>'}</div></div>`}
function goalsPage(){return `<div class="grid three-col">${['daily','weekly','monthly'].map(k=>`<div class="card"><span class="tag">${k.toUpperCase()}</span><h3 style="font-size:19px;margin:14px 0">${state.goals[k]} words</h3>${progress('현재 진행',periodCount(k),state.goals[k])}<button class="btn" data-goal-edit="${k}">목표 수정</button></div>`).join('')}</div><div class="section-heading"><div><h2>My rewards</h2><p>목표를 달성했을 때 스스로에게 줄 보상을 설정하세요.</p></div><button class="btn primary" id="addReward">＋ 보상 추가</button></div><div class="grid two-col">${state.rewards.map(r=>`<div class="card"><div style="display:flex;justify-content:space-between;gap:10px"><div><span class="tag">${r.period.toUpperCase()}</span><h3 style="margin:12px 0 5px">${esc(r.title)}</h3><p class="small muted">${esc(r.description||'')}</p></div><button class="icon-btn" data-reward-edit="${r.id}">···</button></div><div class="settings-row"><span class="small">${r.claimed?'보상 수령 완료':'아직 수령하지 않음'}</span><button class="btn ${r.claimed?'':'soft'}" data-reward-claim="${r.id}">${r.claimed?'수령 취소':'수령 체크'}</button></div></div>`).join('')||'<div class="card empty">아직 보상이 없습니다.</div>'}</div>`}
function settingsPage(){return `<div class="grid two-col"><div class="card"><h3>Data backup</h3><div class="settings-row"><div><strong>Export JSON</strong><p>모든 언어와 학습 기록을 백업합니다.</p></div><button class="btn primary" id="exportData">내보내기</button></div><div class="settings-row"><div><strong>Import JSON</strong><p>백업 파일을 병합하거나 전체 교체합니다.</p></div><button class="btn" id="importData">파일 선택</button></div><input type="file" id="importFile" accept=".json,application/json" class="hidden"></div><div class="card"><h3>Preferences</h3><div class="settings-row"><div><strong>기본 학습 모드</strong><p>학습 화면을 열 때 기본으로 선택할 모드</p></div><select id="defaultMode"><option value="flashcard">Flashcard</option><option value="reverse">Reverse</option><option value="example">Example</option></select></div><div class="settings-row"><div><strong>기본 문제 수</strong><p>테스트 기본 출제 문항 수</p></div><input id="defaultCount" type="number" min="1" max="500" value="${state.settings.defaultQuestionCount}" style="width:85px"></div><div class="settings-row"><div><strong>다음 예문 자동 재생</strong><p>Sentence Copy에서 다음 문장으로 넘어가면 영어 예문을 한 번 읽습니다.</p></div><input id="autoSpeakCopyNext" type="checkbox" ${state.settings.autoSpeakCopyNext?'checked':''}></div></div></div><div class="card" style="margin-top:16px"><h3>Danger zone</h3><div class="settings-row"><div><strong>현재 언어 데이터 초기화</strong><p>선택한 언어의 단어, 단어장, 기록을 삭제합니다.</p></div><button class="btn danger" id="resetLanguage">언어 데이터 초기화</button></div><div class="settings-row"><div><strong>전체 데이터 초기화</strong><p>모든 언어 및 설정을 삭제합니다. 되돌릴 수 없습니다.</p></div><button class="btn danger" id="resetAll">전체 초기화</button></div></div>`}
function openModal(title,body,onSave){$('#modal').innerHTML=`<h2>${title}</h2>${body}<div class="modal-actions"><button class="btn" id="modalCancel">취소</button><button class="btn primary" id="modalSave">저장</button></div>`;$('#modalBackdrop').classList.add('show');$('#modalCancel').onclick=closeModal;$('#modalSave').onclick=()=>{if(onSave()!==false){closeModal();save();render()}}}
function closeModal(){$('#modalBackdrop').classList.remove('show')}
function wordForm(w={}){let bookOptions=books().map(b=>`<label class="small"><input type="checkbox" class="checkbox wordbook-check" value="${b.id}" ${(w.wordbookIds||[]).includes(b.id)?'checked':''}> ${esc(b.name)}</label>`).join('');openModal(w.id?'단어 수정':'새 단어 등록',`<div class="form-grid"><div class="form-group"><label>영단어 *</label><input id="fWord" value="${esc(w.word||'')}" required></div><div class="form-group"><label>한국어 뜻 * (쉼표로 구분)</label><input id="fMeanings" value="${esc((w.meanings||[]).join(', '))}"></div><div class="form-group"><label>품사</label><select id="fPos"><option value="">선택 안 함</option>${[['noun','명사'],['verb','동사'],['adjective','형용사'],['adverb','부사'],['preposition','전치사'],['conjunction','접속사'],['pronoun','대명사'],['phrase','숙어·구문'],['other','기타']].map(([value,label])=>`<option value="${value}" ${w.partOfSpeech===value?'selected':''}>${label}</option>`).join('')}</select></div><div class="form-group"><label>유의어 (쉼표로 구분)</label><input id="fSyn" value="${esc((w.synonyms||[]).join(', '))}"></div><div class="form-group"><label>반의어 (쉼표로 구분)</label><input id="fAnt" value="${esc((w.antonyms||[]).join(', '))}"></div><div class="form-group full"><label>예문 (한 줄에 하나씩, 문장 | 해석 형식)</label><textarea id="fExamples" placeholder="I appreciate your help. | 도움에 감사드립니다.">${esc((w.examples||[]).map(e=>e.text+' | '+(e.translation||'')).join('\\n'))}</textarea></div><div class="form-group full"><label>개인 메모</label><textarea id="fMemo">${esc(w.memo||'')}</textarea></div><div class="form-group full"><label>소속 단어장</label><div class="inline-list">${bookOptions||'<span class="muted small">단어장이 없습니다. Wordbooks에서 먼저 만들어주세요.</span>'}</div></div></div>`,()=>{let wordText=$('#fWord').value.trim(),meanings=$('#fMeanings').value.split(',').map(x=>x.trim()).filter(Boolean);if(!wordText||!meanings.length){notify('영단어와 뜻은 필수 입력 항목입니다.');return false}let duplicate=words().find(x=>x.word.toLowerCase()===wordText.toLowerCase()&&x.id!==w.id);if(duplicate){notify('이미 등록된 단어입니다. 기존 단어를 수정해주세요.');return false}let examples=$('#fExamples').value.split('\n').map(line=>{let [text,...tr]=line.split('|');return {text:text.trim(),translation:tr.join('|').trim()}}).filter(x=>x.text);let obj={...w,id:w.id||uid(),word:wordText,meanings,partOfSpeech:$('#fPos').value,examples,synonyms:$('#fSyn').value.split(',').map(x=>x.trim()).filter(Boolean),antonyms:$('#fAnt').value.split(',').map(x=>x.trim()).filter(Boolean),memo:$('#fMemo').value.trim(),wordbookIds:[...document.querySelectorAll('.wordbook-check:checked')].map(x=>x.value),status:w.status||'learning',createdAt:w.createdAt||new Date().toISOString(),reviewStage:w.reviewStage||0,correctCount:w.correctCount||0,wrongCount:w.wrongCount||0,reviewHistory:w.reviewHistory||[]};if(w.id)Object.assign(w,obj);else words().push(obj);notify('단어가 저장되었습니다.');return true})}
function addRecord(w,type,correct=null){let r={id:uid(),wordId:w.id,languageId:lang(),sessionId:study?.id||quiz?.id||'review',studyType:type,isCorrect:correct,studiedAt:new Date().toISOString()};state.records.push(r);w.lastStudiedAt=r.studiedAt;if(correct===true)w.correctCount++;if(correct===false)w.wrongCount++}
function addWrong(w){let x=state.wrongNotes.find(n=>n.languageId===lang()&&n.wordId===w.id);if(x){x.count++;x.lastWrongAt=new Date().toISOString()}else state.wrongNotes.push({wordId:w.id,languageId:lang(),count:1,lastWrongAt:new Date().toISOString(),wordSnapshot:w.word,meaningSnapshot:w.meanings.join(', ')});w.status='learning';w.masteredAt=null;}
function scheduleReview(w,rating){let steps=[1,3,7,14,30],stage=w.reviewStage||0,days;if(rating==='Again'){stage=0;days=1;w.status='learning';w.wrongCount++}else if(rating==='Hard'){days=stage===0?1:Math.max(1,Math.round(steps[Math.min(stage,4)]*.7));w.status='review'}else if(rating==='Good'){stage=Math.min(5,stage+1);days=steps[Math.min(stage-1,4)];w.status=stage>=5?'mastered':'review'}else{stage=Math.min(5,stage+1);days=steps[Math.min(stage,4)]||30;w.status=stage>=5?'mastered':'review'}w.reviewStage=stage;w.nextReviewAt=dateAdd(today(),days);w.lastReviewResult=rating;w.reviewHistory=w.reviewHistory||[];w.reviewHistory.push({rating,at:new Date().toISOString(),nextReviewAt:w.nextReviewAt});if(rating==='Again')addWrong(w);else{if(stage>=5){w.status='mastered';w.masteredAt=w.masteredAt||new Date().toISOString()}else{w.status='review';w.masteredAt=null}addRecord(w,'review',true)}}

function friendsPage(){return `
<div class="grid two-col friends-grid">
  <section class="card">
    <h2>내 친구 초대 코드</h2>
    <p class="muted small">이 코드를 친구에게 공유하면 친구 신청을 받을 수 있어요.</p>
    <div class="friend-code-row"><code id="friendInviteCode">불러오는 중...</code><button class="btn" id="copyFriendCode" disabled>코드 복사</button></div>
  </section>
  <section class="card">
    <h2>친구 추가</h2>
    <p class="muted small">친구에게 받은 초대 코드를 입력하세요.</p>
    <form id="friendRequestForm" class="friend-add-form">
      <input id="friendCodeInput" type="text" maxlength="10" placeholder="친구 초대 코드" autocomplete="off" required>
      <button class="btn primary" type="submit">친구 신청</button>
    </form>
    <p class="muted small" id="friendActionMessage" aria-live="polite"></p>
  </section>
</div>
<div class="grid two-col friends-grid">
  <section class="card"><h2>받은 친구 신청</h2><div id="pendingFriendsList" class="friend-list"><p class="muted small">불러오는 중...</p></div></section>
  <section class="card"><h2>내 친구</h2><div id="myFriendsList" class="friend-list"><p class="muted small">불러오는 중...</p></div></section>
</div>
<p class="muted small friends-note">현재 친구 기능은 친구 신청과 목록 확인까지 지원합니다. 기상 알림은 다음 단계에서 추가할 예정입니다.</p>
`}
function friendAvatar(url,name){const safeUrl=typeof url==='string'&&/^https:\/\//i.test(url)?url:'';return safeUrl?'<img class="friend-avatar" src="'+esc(safeUrl)+'" alt="">':'<span class="friend-avatar friend-avatar-fallback">'+esc((name||'친구').slice(0,1).toUpperCase())+'</span>'}
async function loadFriendsPage(){
  const api=window.mvFriendsApi;
  if(!api){notify('친구 기능을 불러오지 못했습니다. 새로고침 후 다시 시도해 주세요.');return}
  const codeEl=$('#friendInviteCode');
  const pendingEl=$('#pendingFriendsList');
  const friendsEl=$('#myFriendsList');
  try{
    const [codeResult,pendingResult,friendsResult]=await Promise.all([
      api.getMyInviteCode(),api.getPendingRequests(),api.getMyFriends()
    ]);
    if(codeResult.error)throw codeResult.error;
    if(pendingResult.error)throw pendingResult.error;
    if(friendsResult.error)throw friendsResult.error;
    if(codeEl)codeEl.textContent=codeResult.data?.invite_code||'초대 코드가 없습니다.';
    const copyBtn=$('#copyFriendCode');
    if(copyBtn)copyBtn.disabled=!codeResult.data?.invite_code;
    if(pendingEl){
      const rows=pendingResult.data||[];
      pendingEl.innerHTML=rows.length?rows.map(r=>`
        <div class="friend-row">
          <div class="friend-person">${friendAvatar(r.avatar_url,r.nickname)}<span>${esc(r.nickname||'사용자')}</span></div>
          <div class="friend-actions">
            <button class="btn primary" data-friend-respond="${esc(r.request_id)}" data-accept="true">수락</button>
            <button class="btn" data-friend-respond="${esc(r.request_id)}" data-accept="false">거절</button>
          </div>
        </div>`).join(''):'<p class="muted small">받은 친구 신청이 없습니다.</p>';
    }
    if(friendsEl){
      const rows=friendsResult.data||[];
      friendsEl.innerHTML=rows.length?rows.map(r=>`
        <div class="friend-row">
          <div class="friend-person">${friendAvatar(r.avatar_url,r.nickname)}<span>${esc(r.nickname||'사용자')}</span></div>
          <span class="tag">친구</span>
        </div>`).join(''):'<p class="muted small">아직 친구가 없습니다.</p>';
    }
  }catch(error){
    console.error('Friends load error:',error);
    if(codeEl)codeEl.textContent='불러오지 못했습니다.';
    if(pendingEl)pendingEl.innerHTML='<p class="muted small">친구 신청을 불러오지 못했습니다.</p>';
    if(friendsEl)friendsEl.innerHTML='<p class="muted small">친구 목록을 불러오지 못했습니다.</p>';
    notify(error.message||'친구 정보를 불러오지 못했습니다.');
  }
}

function bindPage(){if(page==='friends'){loadFriendsPage();$('#friendRequestForm')?.addEventListener('submit',async e=>{e.preventDefault();const input=$('#friendCodeInput');const message=$('#friendActionMessage');const code=input.value.trim().toUpperCase();if(!code)return;const btn=e.submitter; if(btn)btn.disabled=true;if(message)message.textContent='친구 신청을 보내는 중...';try{const result=await window.mvFriendsApi.sendFriendRequest(code);if(result.error)throw result.error;if(message)message.textContent=result.data||'친구 신청을 보냈습니다.';input.value='';}catch(error){if(message)message.textContent=error.message||'친구 신청에 실패했습니다.';}finally{if(btn)btn.disabled=false;}});$('#copyFriendCode')?.addEventListener('click',async()=>{const code=$('#friendInviteCode')?.textContent||'';if(!code||code==='불러오는 중...'||code==='불러오지 못했습니다.')return;try{await navigator.clipboard.writeText(code);notify('초대 코드를 복사했습니다.')}catch{prompt('친구에게 공유할 초대 코드입니다.',code)}});$('#pendingFriendsList')?.addEventListener('click',async e=>{const btn=e.target.closest('[data-friend-respond]');if(!btn)return;btn.disabled=true;try{const result=await window.mvFriendsApi.respondToRequest(btn.dataset.friendRespond,btn.dataset.accept==='true');if(result.error)throw result.error;notify(result.data||'친구 신청 상태를 변경했습니다.');await loadFriendsPage();}catch(error){notify(error.message||'요청 처리에 실패했습니다.');btn.disabled=false;}});}document.querySelectorAll('[data-language-tab]').forEach(b=>b.onclick=()=>{state.activeLanguageId=b.dataset.languageTab;save();render()});$('#inlineAddLanguage')?.addEventListener('click',addLanguage);document.querySelectorAll('[data-language-edit]').forEach(b=>b.onclick=()=>editLanguage(b.dataset.languageEdit));document.querySelectorAll('[data-language-delete]').forEach(b=>b.onclick=()=>deleteLanguage(b.dataset.languageDelete));document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>nav(b.dataset.go));$('#addWord')?.addEventListener('click',()=>wordForm());$('#wordSearch')?.addEventListener('input',e=>{wordFilter=e.target.value;let pos=e.target.selectionStart;render();$('#wordSearch').focus();$('#wordSearch').setSelectionRange(pos,pos)});$('#sortWords')?.addEventListener('change',e=>{wordSort=e.target.value;render()});['statusFilter','bookFilter'].forEach(id=>$('#'+id)?.addEventListener('change',()=>{let s=$('#statusFilter').value,b=$('#bookFilter').value;render();$('#statusFilter').value=s;$('#bookFilter').value=b}));document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>showDetail(b.dataset.detail));document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>wordForm(word(b.dataset.edit)));document.querySelectorAll('.row-select').forEach(b=>b.onchange=()=>{b.checked?selectedIds.add(b.dataset.id):selectedIds.delete(b.dataset.id);render()});$('#selectAll')?.addEventListener('change',e=>{document.querySelectorAll('.row-select').forEach(x=>e.target.checked?selectedIds.add(x.dataset.id):selectedIds.delete(x.dataset.id));render()});$('#bulkDelete')?.addEventListener('click',()=>{if(confirm(`${selectedIds.size}개 단어를 삭제할까요? 관련 학습 기록은 보존됩니다.`)){bucket().words=bucket().words.filter(w=>!selectedIds.has(w.id));selectedIds.clear();save();render()}});$('#addBook')?.addEventListener('click',()=>bookForm());document.querySelectorAll('[data-book-edit]').forEach(b=>b.onclick=()=>bookForm(books().find(x=>x.id===b.dataset.bookEdit)));document.querySelectorAll('[data-book-study]').forEach(b=>b.onclick=()=>startStudy('flashcard',b.dataset.bookStudy,10,'random'));$('#startStudy')?.addEventListener('click',()=>startStudy($('#studyMode').value,$('#studyBook').value,Number($('#studyCount').value),$('#studyOrder').value));$('#revealMeaning')?.addEventListener('click',()=>{study.revealed=true;render()});$('#playStudyPronunciation')?.addEventListener('click',()=>speakStudyWord());document.querySelectorAll('[data-speak-example]').forEach(b=>b.addEventListener('click',()=>{const w=word(study.ids[study.index]);const ex=w?.examples?.filter(e=>e.text?.trim())?.[Number(b.dataset.speakExample)];if(ex?.text)speakStudyWord(ex.text)}));$('#checkStudySpelling')?.addEventListener('click',checkStudySpelling);$('#checkStudyCopy')?.addEventListener('click',checkStudyCopy);$('#studyCopyAnswer')?.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();checkStudyCopy()}});$('#retryStudyCopy')?.addEventListener('click',retryStudyCopy);$('#studyNextCopy')?.addEventListener('click',()=>moveStudy(1));$('#studySpellingAnswer')?.addEventListener('keydown',e=>{if(e.key==='Enter')checkStudySpelling()});$('#studyNextSpelling')?.addEventListener('click',()=>moveStudy(1));$('#know')?.addEventListener('click',()=>rateStudy(true));$('#dontKnow')?.addEventListener('click',()=>rateStudy(false));$('#studyNext')?.addEventListener('click',()=>moveStudy(1));$('#studyPrev')?.addEventListener('click',()=>moveStudy(-1));$('#endStudy')?.addEventListener('click',()=>{study=null;save();render()});$('#startQuiz')?.addEventListener('click',()=>startQuiz($('#quizMode').value,Number($('#quizCount').value),$('#quizBook').value,$('#quizFilter').value));document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>answerQuiz(quiz.items[quiz.index].options[Number(b.dataset.choice)].value));$('#checkAnswer')?.addEventListener('click',()=>answerQuiz($('#quizAnswer').value));$('#quizAnswer')?.addEventListener('keydown',e=>{if(e.key==='Enter')answerQuiz(e.target.value)});$('#nextQuestion')?.addEventListener('click',nextQuestion);$('#retryQuiz')?.addEventListener('click',()=>{let ids=quiz.items.map(x=>x.id);startQuiz('random',ids.length,'all','all',ids)});$('#endQuiz')?.addEventListener('click',()=>{quiz=null;render()});$('#quitQuiz')?.addEventListener('click',()=>{if(confirm('테스트를 종료할까요?')){quiz=null;render()}});$('#startReview')?.addEventListener('click',()=>{reviewQueue=dueWords().map(w=>w.id);reviewIndex=0;render()});$('#reviewReveal')?.addEventListener('click',()=>$('#reviewAnswer').classList.remove('hidden'));document.querySelectorAll('[data-rate]').forEach(b=>b.onclick=()=>{let w=word(reviewQueue[reviewIndex]);scheduleReview(w,b.dataset.rate);reviewIndex++;save();if(reviewIndex>=reviewQueue.length){reviewQueue=[];reviewIndex=0;notify('복습이 완료되었습니다.')}render()});document.querySelectorAll('[data-wrong-delete]').forEach(b=>b.onclick=()=>{state.wrongNotes=state.wrongNotes.filter(x=>!(x.languageId===lang()&&x.wordId===b.dataset.wrongDelete));save();render()});$('#wrongStudy')?.addEventListener('click',()=>startStudy('flashcard','all',500,'random',state.wrongNotes.filter(x=>x.languageId===lang()).map(x=>x.wordId)));$('#wrongQuiz')?.addEventListener('click',()=>startQuiz('random',500,'all','all',state.wrongNotes.filter(x=>x.languageId===lang()).map(x=>x.wordId)));document.querySelectorAll('[data-goal-edit]').forEach(b=>b.onclick=()=>{let k=b.dataset.goalEdit,val=prompt(`${k} 목표 단어 수`,state.goals[k]);if(val!==null&&Number(val)>0){state.goals[k]=Number(val);save();render()}});$('#addReward')?.addEventListener('click',()=>rewardForm());document.querySelectorAll('[data-reward-edit]').forEach(b=>b.onclick=()=>rewardForm(state.rewards.find(x=>x.id===b.dataset.rewardEdit)));document.querySelectorAll('[data-reward-claim]').forEach(b=>b.onclick=()=>{let r=state.rewards.find(x=>x.id===b.dataset.rewardClaim);r.claimed=!r.claimed;save();render()});$('#exportData')?.addEventListener('click',exportData);$('#importData')?.addEventListener('click',()=>$('#importFile').click());$('#importFile')?.addEventListener('change',importData);$('#defaultMode')&&(($('#defaultMode').value=state.settings.defaultStudyMode),$('#defaultMode').onchange=e=>{state.settings.defaultStudyMode=e.target.value;save()});$('#defaultCount')?.addEventListener('change',e=>{state.settings.defaultQuestionCount=Math.max(1,Number(e.target.value)||10);save()});$('#autoSpeakCopyNext')?.addEventListener('change',e=>{state.settings.autoSpeakCopyNext=e.target.checked;save()});$('#resetLanguage')?.addEventListener('click',()=>{if(confirm('현재 언어의 모든 학습 데이터를 삭제할까요?')){delete state.data[lang()];state.records=state.records.filter(r=>r.languageId!==lang());state.wrongNotes=state.wrongNotes.filter(r=>r.languageId!==lang());save();render()}});$('#resetAll')?.addEventListener('click',()=>{if(confirm('전체 데이터를 영구 삭제할까요?')){state=defaults();save();nav('dashboard')}})}
function showDetail(id){let w=word(id);if(!w)return;openModal(w.word,`<p class="study-meaning">${esc(w.meanings.join(', '))}</p><p class="small muted">${esc(w.partOfSpeech||'품사 미지정')}</p><h3>Examples</h3>${w.examples.map(e=>`<p class="small">${esc(e.text)}<br><span class="muted">${esc(e.translation)}</span></p>`).join('')||'<p class="small muted">예문 없음</p'}<h3>Synonyms / Antonyms</h3><p class="small">유의어: ${esc(w.synonyms.join(', ')||'—')}</p><p class="small">반의어: ${esc(w.antonyms.join(', ')||'—')}</p><h3>Memo</h3><p class="small">${esc(w.memo||'—')}</p><p class="small muted">다음 복습: ${w.nextReviewAt||'일정 없음'} · ${statusLabel(w.status)}</p>`,()=>{return true});$('#modalSave').textContent='닫기';$('#modalSave').onclick=closeModal;$('#modalCancel').classList.add('hidden')}
function bookForm(b){openModal(b?'단어장 수정':'단어장 만들기',`<div class="form-grid"><div class="form-group full"><label>단어장 이름 *</label><input id="bookName" value="${esc(b?.name||'')}"></div><div class="form-group full"><label>설명</label><textarea id="bookDesc">${esc(b?.description||'')}</textarea></div></div>`,()=>{let name=$('#bookName').value.trim();if(!name){notify('단어장 이름을 입력해주세요.');return false}if(b){b.name=name;b.description=$('#bookDesc').value.trim()}else books().push({id:uid(),name,description:$('#bookDesc').value.trim(),createdAt:new Date().toISOString()});return true});if(b){let old=$('#modalSave').onclick;$('#modal').insertAdjacentHTML('beforeend','<button class="btn danger" id="deleteBook">단어장 삭제</button>');$('#deleteBook').onclick=()=>{if(confirm('단어장을 삭제할까요? 단어 자체는 삭제되지 않습니다.')){bucket().wordbooks=bucket().wordbooks.filter(x=>x.id!==b.id);words().forEach(w=>w.wordbookIds=w.wordbookIds.filter(id=>id!==b.id));closeModal();save();render()}}}}
function rewardForm(r){openModal(r?'보상 수정':'보상 추가',`<div class="form-grid"><div class="form-group"><label>연결 목표</label><select id="rewardPeriod">${['daily','weekly','monthly'].map(p=>`<option ${r?.period===p?'selected':''}>${p}</option>`).join('')}</select></div><div class="form-group"><label>보상 이름 *</label><input id="rewardTitle" value="${esc(r?.title||'')}"></div><div class="form-group full"><label>상세 설명</label><textarea id="rewardDesc">${esc(r?.description||'')}</textarea></div></div>`,()=>{let title=$('#rewardTitle').value.trim();if(!title){notify('보상 이름을 입력해주세요.');return false}if(r)Object.assign(r,{period:$('#rewardPeriod').value,title,description:$('#rewardDesc').value.trim()});else state.rewards.push({id:uid(),period:$('#rewardPeriod').value,title,description:$('#rewardDesc').value.trim(),claimed:false});return true});if(r){$('#modal').insertAdjacentHTML('beforeend','<button class="btn danger" id="deleteReward">삭제</button>');$('#deleteReward').onclick=()=>{state.rewards=state.rewards.filter(x=>x.id!==r.id);closeModal();save();render()}}}
function startStudy(mode,bookId,count,order,idsOverride){let pool=idsOverride?idsOverride.map(word).filter(Boolean):words().filter(w=>bookId==='all'||w.wordbookIds.includes(bookId));pool=pool.filter(w=>w.status!=='mastered'||idsOverride);if(mode==='copy')pool=pool.filter(w=>w.examples?.some(e=>e.text?.trim()));if(order==='random')pool.sort(()=>Math.random()-.5);pool=pool.slice(0,Math.max(1,count||10));if(!pool.length){notify(mode==='copy'?'예문이 등록된 단어가 없습니다. 먼저 단어에 예문을 추가해 주세요.':'학습할 단어가 없습니다.');return}study={id:uid(),mode,ids:pool.map(w=>w.id),index:0,revealed:false,checked:false,correct:false,answer:''};page='study';render();}
function rateStudy(known){let w=word(study.ids[study.index]);if(known){addRecord(w,'study',true);w.reviewStage=Math.max(1,w.reviewStage||0);w.nextReviewAt=w.nextReviewAt||dateAdd(today(),1)}else{addRecord(w,'study',false);addWrong(w);w.nextReviewAt=dateAdd(today(),1)}save();moveStudy(1)}
function speakStudyWord(textOverride){
const w=study&&word(study.ids[study.index]);if(!w)return;
if(!('speechSynthesis' in window)||!('SpeechSynthesisUtterance' in window)){notify('이 브라우저는 음성 재생을 지원하지 않습니다.');return}
const speechText=(textOverride||((study.mode==='copy'||study.mode==='example')?(w.examples?.[0]?.text||''):w.word)).trim();
if(!speechText){notify('읽을 문장이 없습니다.');return}
window.speechSynthesis.cancel();
const utterance=new SpeechSynthesisUtterance(speechText);
utterance.lang='en-US';utterance.rate=0.85;utterance.pitch=1;
const voices=window.speechSynthesis.getVoices();
const voice=voices.find(v=>v.lang&&v.lang.toLowerCase()==='en-us');
if(voice)utterance.voice=voice;
window.speechSynthesis.speak(utterance);
}
function checkStudyCopy(){if(!study||study.checked)return;const input=$('#studyCopyAnswer')?.value.trim()||'';if(!input){notify('예문을 입력해 주세요.');return}const w=word(study.ids[study.index]);const ex=w?.examples?.[0];if(!ex?.text)return;study.answer=input;study.correct=norm(input)===norm(ex.text);study.checked=true;addRecord(w,'study',study.correct);if(study.correct){w.reviewStage=Math.max(1,w.reviewStage||0);w.nextReviewAt=w.nextReviewAt||dateAdd(today(),1)}else{addWrong(w);w.nextReviewAt=dateAdd(today(),1)}save();render()}
function retryStudyCopy(){if(!study)return;study.checked=false;study.correct=false;study.answer='';render();$('#studyCopyAnswer')?.focus()}
function checkStudySpelling(){if(!study||study.checked)return;const input=$('#studySpellingAnswer')?.value.trim()||'';if(!input){notify('영어 스펠링을 입력해주세요.');return}const w=word(study.ids[study.index]);if(!w)return;study.answer=input;study.correct=norm(input)===norm(w.word);study.checked=true;if(study.correct){addRecord(w,'study',true);w.reviewStage=Math.max(1,w.reviewStage||0);w.nextReviewAt=w.nextReviewAt||dateAdd(today(),1)}else{addRecord(w,'study',false);addWrong(w);w.nextReviewAt=dateAdd(today(),1)}save();render()}
function moveStudy(n){study.index+=n;study.revealed=false;study.checked=false;study.correct=false;study.answer='';if(study.index<0)study.index=0;if(study.index>=study.ids.length){study=null;notify('학습 세션이 완료되었습니다.')}render();if(study?.mode==='copy'&&state.settings.autoSpeakCopyNext)speakStudyWord()}
function startQuiz(mode,count,bookId,filter,idsOverride){let pool=idsOverride?idsOverride.map(word).filter(Boolean):words().filter(w=>bookId==='all'||w.wordbookIds.includes(bookId));if(filter==='wrong')pool=pool.filter(w=>state.wrongNotes.some(x=>x.languageId===lang()&&x.wordId===w.id));else if(filter!=='all')pool=pool.filter(w=>w.status===filter);if(!pool.length){notify('출제할 단어가 없습니다.');return}pool.sort(()=>Math.random()-.5);pool=pool.slice(0,Math.max(1,count||10));let items=pool.map(w=>{let type=mode==='random'?['multiple','typing','typing'][Math.floor(Math.random()*3)]:mode;let direction=Math.random()<.5?'en-ko':'ko-en';if(type==='multiple'){let distract=words().filter(x=>x.id!==w.id&&x.meanings.length).sort(()=>Math.random()-.5).slice(0,3).map(x=>({value:direction==='en-ko'?x.meanings[0]:x.word,correct:false}));if(distract.length<3)type='typing';else{let options=[{value:direction==='en-ko'?w.meanings[0]:w.word,correct:true},...distract].sort(()=>Math.random()-.5);return{id:w.id,type:'multiple',direction,options}}}return{id:w.id,type:'typing',direction}});quiz={id:uid(),mode,items,index:0,correct:0,missed:[],answered:false,done:false};page='quiz';render()}
function answerQuiz(value){if(quiz.answered)return;let item=quiz.items[quiz.index],w=word(item.id),correct;if(item.direction==='en-ko'){let target=w.meanings.map(norm);correct=target.includes(norm(value))}else correct=norm(value)===norm(w.word);quiz.answered=true;quiz.lastCorrect=correct;quiz.answer=value;quiz.selected=value;if(correct)quiz.correct++;else{quiz.missed.push(w);addWrong(w)}addRecord(w,'quiz',correct);save();render()}
function norm(s){return String(s||'').trim().toLowerCase().replace(/\s+/g,' ')}
function nextQuestion(){quiz.index++;quiz.answered=false;quiz.answer='';if(quiz.index>=quiz.items.length)quiz.done=true;render()}
function exportData(){let blob=new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`my-vocabulary-backup-${today()}.json`;a.click();URL.revokeObjectURL(a.href);notify('JSON 백업 파일을 생성했습니다.')}
function importData(e){let file=e.target.files[0];if(!file)return;let reader=new FileReader();reader.onload=()=>{try{let incoming=JSON.parse(reader.result);if(!incoming.version||!Array.isArray(incoming.languages)||!incoming.data||!Array.isArray(incoming.records)||!Array.isArray(incoming.wrongNotes))throw Error('지원하지 않는 백업 형식입니다.');let mode=prompt('가져오기 방식을 입력하세요: merge 또는 replace','merge');if(!['merge','replace'].includes(mode))return;if(mode==='replace')state=incoming;else{let existingIds=new Set(state.languages.map(x=>x.id));incoming.languages.forEach(l=>{if(!existingIds.has(l.id))state.languages.push(l)});Object.entries(incoming.data).forEach(([id,d])=>{if(!state.data[id])state.data[id]=d;else{let have=new Set(state.data[id].words.map(w=>w.id));d.words.forEach(w=>{if(!have.has(w.id))state.data[id].words.push(w)});let bHave=new Set(state.data[id].wordbooks.map(b=>b.id));d.wordbooks.forEach(b=>{if(!bHave.has(b.id))state.data[id].wordbooks.push(b)})}});['records','wrongNotes','sessions'].forEach(k=>{let have=new Set(state[k].map(x=>x.id||x.wordId));(incoming[k]||[]).forEach(x=>{if(!have.has(x.id||x.wordId))state[k].push(x)})});state.rewards.push(...(incoming.rewards||[]).filter(x=>!state.rewards.some(y=>y.id===x.id)))}save();notify('데이터를 가져왔습니다.');render()}catch(err){alert('파일을 읽을 수 없습니다: '+err.message)}e.target.value=''};reader.readAsText(file)}
function editLanguage(id){
const l=state.languages.find(x=>x.id===id);if(!l)return;
openModal('학습 언어 수정','<div class="form-grid"><div class="form-group"><label>언어 이름 *</label><input id="langName" value="'+esc(l.name)+'" placeholder="예: Japanese"></div><div class="form-group"><label>표시 이름</label><input id="langNative" value="'+esc(l.nativeName||'')+'" placeholder="예: 일본어"></div></div>',()=>{
const name=$('#langName').value.trim();if(!name){notify('언어 이름을 입력해주세요.');return false}
if(state.languages.some(x=>x.id!==id&&x.name.toLowerCase()===name.toLowerCase())){notify('이미 등록된 언어 이름입니다.');return false}
l.name=name;l.nativeName=$('#langNative').value.trim();notify('언어 정보가 수정되었습니다.');return true
});}
function deleteLanguage(id){
const l=state.languages.find(x=>x.id===id);if(!l)return;
if(state.languages.length<=1){notify('마지막으로 남은 언어는 삭제할 수 없습니다.');return}
const d=state.data[id]||{words:[],wordbooks:[]};const count=d.words?.length||0;const bookCount=d.wordbooks?.length||0;
if(!confirm((l.nativeName||l.name)+' 언어를 삭제할까요?\\n등록된 단어 '+count+'개와 단어장 '+bookCount+'개도 함께 삭제됩니다.\\n관련 학습 기록과 오답 기록도 삭제됩니다.'))return;
state.languages=state.languages.filter(x=>x.id!==id);delete state.data[id];
state.records=state.records.filter(x=>x.languageId!==id);state.wrongNotes=state.wrongNotes.filter(x=>x.languageId!==id);state.sessions=state.sessions.filter(x=>x.languageId!==id);
if(state.activeLanguageId===id)state.activeLanguageId=state.languages[0].id;save();render();notify('언어와 관련 데이터가 삭제되었습니다.');
}
function addLanguage(){openModal('학습 언어 추가',`<div class="form-grid"><div class="form-group"><label>언어 이름 *</label><input id="langName" placeholder="예: Japanese"></div><div class="form-group"><label>표시 이름</label><input id="langNative" placeholder="예: 일본어"></div></div>`,()=>{let name=$('#langName').value.trim();if(!name){notify('언어 이름을 입력해주세요.');return false}let id=uid();state.languages.push({id,name,nativeName:$('#langNative').value.trim(),createdAt:new Date().toISOString()});state.data[id]={words:[],wordbooks:[]};state.activeLanguageId=id;return true})}
$('#mainNav').addEventListener('click',e=>{let b=e.target.closest('[data-page]');if(b)nav(b.dataset.page)});$('#activeLanguage').addEventListener('change',e=>{state.activeLanguageId=e.target.value;save();render()});$('#addLanguageBtn').addEventListener('click',addLanguage);$('#mobileMenu').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));$('#modalBackdrop').addEventListener('click',e=>{if(e.target.id==='modalBackdrop')closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});save();render();
})();